// Replays an Aircall-compatible `call.ended` webhook so the workflow can be demoed
// without an Aircall account. Output shape == what the Webhook node emits.
//
//  Pick the scenario
//   sales         new prospect, 30 seats, wants pricing          → Deal + Task
//   support       existing customer, calls dropping              → Ticket + Task
//   cancellation  existing customer threatening to cancel         → Churn risk + CSM task
//   review        ambiguous 25-second call                        → Human review
//   injection     prospect tries to talk the AI into a discount   → Human review
const SCENARIO = 'sales';

const scenarios = {
  sales:        { id: 82939101, phone: '+61400111222', talk: 400 },
  support:      { id: 82939102, phone: '+61400333444', talk: 310 },
  cancellation: { id: 82939103, phone: '+61400555666', talk: 260 },
  review:       { id: 82939104, phone: '+61400777888', talk: 25 },
  injection:    { id: 82939105, phone: '+61400999000', talk: 180 },
};
const s = scenarios[SCENARIO];
if (!s) throw new Error(`Unknown SCENARIO "${SCENARIO}". Use one of: ${Object.keys(scenarios).join(', ')}`);

const now = Math.floor(Date.now() / 1000);
const startedAt = now - s.talk - 40;
const body = {
  resource: 'call',
  event: 'call.ended',
  timestamp: now,
  token: 'demo-webhook-token',
  data: {
    id: s.id,
    direction: 'inbound',
    status: 'done',
    started_at: startedAt,
    answered_at: startedAt + 10,
    ended_at: startedAt + 10 + s.talk,
    duration: s.talk + 10,
    raw_digits: s.phone,
    user: { id: 123, name: 'Jordan Lee', email: 'jordan.lee@example.com' },
    number: { id: 456, name: 'AU Sales Line', digits: '+61 2 8000 0000' },
  },
};

return [{ json: { headers: { 'content-type': 'application/json' }, params: {}, query: {}, body, _demo: true, _scenario: SCENARIO } }];

//
// DEPLOYMENT CONFIG : the only node you edit per customer.
// Everything downstream reads from here, so the same workflow is reusable
// across accounts, CRMs pipelines and alert channels.
//
const config = {
  workflow_version: '1.0.0',

  // Aircall sends `token` in every webhook payload. Map each token to the account
  // it belongs to; unknown tokens are rejected. (Multi-account ready.)
  accounts: {
    'demo-webhook-token': { name: 'Demo Aircall Account' },
  },

  // Which Aircall event drives processing.
  //  - 'call.ended'            → demo / fixture transcripts (fires ~30s after hang-up)
  //  - 'transcription.created' → production with Conversation Intelligence enabled
  //                              (transcript guaranteed to exist when the event fires)
  processing_event: 'call.ended',

  // Live vs dry-run switches. Dry run = the exact request is built and logged
  // in the execution, but not sent.
  aircall_live: false,   // true → fetch transcript from Aircall + tag/comment the call
  slack_webhook_url: '', // Slack incoming-webhook URL; empty → dry run

  // AI configuration
  openai_model: 'gpt-4.1-mini',
  openai_temperature: 0,        // set to null for models that only accept the default
  confidence_threshold: 0.85,   // below this: human review; intake and audit notes may already exist

  hubspot: {
    portal_id: '',              // optional: enables "Open in HubSpot" links in Slack
    deal_pipeline: 'default',
    // AI may *suggest* a stage; policy only lets it use these early stages.
    allowed_deal_stages: ['appointmentscheduled', 'qualifiedtobuy', 'presentationscheduled'],
    default_deal_stage: 'qualifiedtobuy',
    price_per_seat_monthly: 40, // pipeline amount estimate only (seats × price × 12)
    ticket_pipeline: '0',
    ticket_stage: '1',
    // HubSpot owner IDs per team. Empty → contact owner, else unassigned.
    owners: { sales: '', support: '', customer_success: '' },
    // Created by the "00 · Setup" workflow: aircall_last_intent, aircall_last_call_id,
    // aircall_churn_risk. Set false if you skipped setup.
    custom_properties_enabled: true,
  },

  // Task due dates (hours from now) per route
  sla_hours: { sales: 24, support: 4, cancellation: 4, general: 48, review: 8 },

  // Aircall tag IDs (GET /v1/tags). null → tag skipped, comment still posted.
  aircall_tag_ids: {
    'AI-QUALIFIED-LEAD': null,
    'AI-SUPPORT-ISSUE': null,
    'AI-CHURN-RISK': null,
    'AI-NEEDS-REVIEW': null,
    'AI-PROCESSED': null,
  },

  idempotency_ttl_days: 14,
  // A failed/crashed run keeps its lock this long before a redelivery may re-claim it.
  // (n8n "Retry" on the failed execution bypasses this : it resumes at the failed node.)
  idempotency_lock_minutes: 15,

  // API base URLs (overridable for sandboxes / mock servers)
  endpoints: {
    hubspot: 'https://api.hubapi.com',
    openai: 'https://api.openai.com/v1',
    aircall: 'https://api.aircall.io/v1',
  },
};


return $input.all().map((item) => ({ json: { config, request: item.json } }));

// Aircall includes a per-webhook `token` in every payload. We use it to verify the
// event is genuine and to identify which Aircall account it belongs to.
// The token itself is NOT passed downstream.
const { config, request } = $input.first().json;
const body = request.body ?? {};
const account = config.accounts[body.token];

return [{
  json: {
    valid: Boolean(account),
    account: account?.name ?? null,
    reason: account ? null : body.token ? 'unknown_token' : 'missing_token',
    source: request._demo ? `demo_fixture:${request._scenario}` : 'aircall_webhook',
    received_at: new Date().toISOString(),
    body: { ...body, token: undefined },
  },
}];

// Map Aircall's provider-specific payload onto our canonical call object.
// Everything downstream (CRM, AI, alerts) depends on THIS shape, not Aircall's,
// so swapping the telephony provider only touches this node.
const cfg = $('Config').first().json.config;
const { body, account, source, received_at } = $input.first().json;
const d = body.data ?? {};

const isTranscriptEvent = String(body.event ?? '').startsWith('transcription.');
const call = isTranscriptEvent ? (d.call ?? {}) : d;
const callId = String(isTranscriptEvent ? (d.call_id ?? d.call?.id ?? d.id) : d.id);

const num = (v) => (v === null || v === undefined || v === '' ? null : Number(v));
const startedAt = num(call.started_at);
const answeredAt = num(call.answered_at);
const endedAt = num(call.ended_at);

function toE164(raw) {
  if (!raw) return null;
  const cleaned = String(raw).replace(/[^\d+]/g, '');
  if (cleaned.replace('+', '').length < 6) return null; // "anonymous", extensions, junk
  return cleaned.startsWith('+') ? cleaned : `+${cleaned}`;
}
const phone = toE164(call.raw_digits);

// dispatch: process | skip (right event, nothing to analyse) | ignore (other events)
let dispatch = 'process';
let skipReason = null;
if (body.event !== cfg.processing_event) {
  dispatch = 'ignore';
  skipReason = `event "${body.event}" is not the processing event ("${cfg.processing_event}")`;
} else if (!isTranscriptEvent && !answeredAt) {
  dispatch = 'skip';
  skipReason = 'call was not answered : no conversation to analyse';
} else if (!phone) {
  dispatch = 'skip';
  skipReason = 'no usable caller number (anonymous / withheld / missing call details)';
}

return [{
  json: {
    call_id: callId,
    event: body.event,
    idempotency_key: `aircall:${body.event}:${callId}`,
    dispatch,
    skip_reason: skipReason,
    phone,
    direction: call.direction ?? null,
    started_at: startedAt,
    answered_at: answeredAt,
    ended_at: endedAt,
    duration_seconds: num(call.duration) ?? (startedAt && endedAt ? endedAt - startedAt : null),
    talk_seconds: answeredAt && endedAt ? endedAt - answeredAt : null,
    agent: {
      id: call.user?.id != null ? String(call.user.id) : null,
      name: call.user?.name ?? null,
      email: call.user?.email ?? null,
    },
    aircall_line: call.number?.name ?? null,
    account,
    source,
    event_timestamp: num(body.timestamp),
    received_at,
  },
}];

// Webhook providers retry delivery, so CRM side effects must be idempotent.
// Key: aircall:<event>:<call_id>
//
//  completed            → duplicate, stop
//  in_progress < lock   → another execution is handling it (or just failed), stop
//  in_progress ≥ lock   → previous attempt died, allow reprocessing
//
// Stored in n8n workflow static data (persists for production executions only :
// manual test runs always process, which is handy for demos). Swap for the
// Postgres table in sql/idempotency_postgres.sql for multi-worker deployments.
const cfg = $('Config').first().json.config;
const evt = $input.first().json;
const store = $getWorkflowStaticData('global');
store.processed = store.processed ?? {};

const now = Date.now();
const ttlMs = cfg.idempotency_ttl_days * 24 * 3600 * 1000;
for (const [key, rec] of Object.entries(store.processed)) {
  if (now - rec.at > ttlMs) delete store.processed[key];
}

const STALE_MS = cfg.idempotency_lock_minutes * 60 * 1000;
const prior = store.processed[evt.idempotency_key];
let duplicate = false;
let duplicateReason = null;
if (prior?.status === 'completed') {
  duplicate = true;
  duplicateReason = `already processed by execution ${prior.execution_id}`;
} else if (prior?.status === 'in_progress' && now - prior.at < STALE_MS) {
  duplicate = true;
  duplicateReason = `in flight in execution ${prior.execution_id}`;
}

if (!duplicate) {
  store.processed[evt.idempotency_key] = { status: 'in_progress', at: now, execution_id: $execution.id };
}

return [{ json: { ...evt, duplicate, duplicate_reason: duplicateReason } }];

