const buttons = [];
if (needsApproval) {
  buttons.push({ type: 'button', style: 'primary', text: { type: 'plain_text', text: '✅ Approve draft' }, url: approveUrl });
  buttons.push({ type: 'button', style: 'danger', text: { type: 'plain_text', text: '✖ Reject' }, url: rejectUrl });
}
const contactUrl = hubspotUrl('0-1', crm.contact_id);
if (contactUrl) buttons.push({ type: 'button', text: { type: 'plain_text', text: 'Open in HubSpot' }, url: contactUrl });
if (buttons.length) blocks.push({ type: 'actions', elements: buttons });

const slack_payload = { text: `${HEADERS[policy.route]} : ${company ?? name}`, blocks };

//  Aircall write-back
const tagName = TAGS[policy.route];
const tagId = cfg.aircall_tag_ids[tagName];
const comment = [
  `🤖 ${tagName}`,
  a.summary,
  a.seat_count ? `Seats: ${a.seat_count}` : null,
  a.current_provider ? `Current provider: ${a.current_provider}` : null,
  a.timeline ? `Timeline: ${a.timeline}` : null,
  `Next action: ${a.next_action_detail}`,
  policy.route === 'review' ? `Held for review: ${policy.review_reasons.join('; ')}` : null,
  `HubSpot: ${crmLine}`,
  `AI confidence: ${pct(a.confidence)}`,
].filter(Boolean).join('\n').slice(0, 1500);

return [{
  json: {
    ...base,
    crm,
    notification: { slack_payload, needs_approval: needsApproval, approve_url: approveUrl, reject_url: rejectUrl },
    aircall_writeback: {
      tag_name: tagName,
      tag_ids: tagId ? [tagId] : [],
      tag_skipped_reason: tagId ? null : `no Aircall tag ID configured for ${tagName}`,
      comment,
    },
  },
}];

// One audit record per processed call + mark the idempotency key completed.
// This is what answers "what did the automation do, and why?".
const cfg = $('Config').first().json.config;
const c = $('Compose Notification').first().json;
const store = $getWorkflowStaticData('global');
const pick = (name) => ($(name).isExecuted ? $(name).first().json : null);

const slackResult = pick('Slack: Send Alert');
const slack = !cfg.slack_webhook_url ? 'dry_run' : slackResult?.error ? `failed: ${slackResult.error.message ?? slackResult.error}` : 'sent';

const tag = pick('Aircall: Tag Call');
const comment = pick('Aircall: Comment Call');
const aircall = !cfg.aircall_live
  ? { mode: 'dry_run', would_send: { tags: c.aircall_writeback.tag_ids, comment: c.aircall_writeback.comment } }
  : {
    mode: 'live',
    tag: c.aircall_writeback.tag_ids.length ? tag?.statusCode ?? 'not_sent' : 'skipped_no_tag_id',
    comment: comment?.statusCode ?? 'not_sent',
  };

const nowMs = Date.now();
const record = {
  call_id: c.call_id,
  idempotency_key: c.idempotency_key,
  workflow_version: cfg.workflow_version,
  execution_id: $execution.id,
  source: c.source,
  status: c.notification.needs_approval ? 'completed_awaiting_approval' : 'completed',
  route: c.policy.route,
  intent: c.analysis.intent,
  intent_from_model: c.analysis.intent_from_model,
  ai_confidence: c.analysis.confidence,
  automation_allowed: c.policy.automation_allowed,
  review_reasons: c.policy.review_reasons,
  policy_corrections: c.policy.corrections,
  draft_flags: c.policy.draft_flags,
  hubspot_contact_id: c.crm.contact_id,
  is_new_contact: c.customer.is_new_contact,
  hubspot_note_id: c.crm.note_id ?? null,
  hubspot_company_id: c.crm.company_id ?? null,
  deal_id: c.crm.deal_id ?? null,
  ticket_id: c.crm.ticket_id ?? null,
  task_id: c.crm.task_id ?? null,
  slack,
  aircall_writeback: aircall,
  ai_model: c.ai_meta.model,
  ai_tokens: c.ai_meta.usage?.total_tokens ?? null,
  prompt_version: c.ai_meta.prompt_version,
  end_to_end_seconds: c.ended_at ? Math.round(nowMs / 1000 - c.ended_at) : null,
  processed_at: new Date(nowMs).toISOString(),
  approval: c.notification.needs_approval ? 'pending' : 'not_required',
};

store.audit = [record, ...(store.audit ?? [])].slice(0, 500);
store.processed = store.processed ?? {};
store.processed[c.idempotency_key] = { status: 'completed', at: nowMs, execution_id: $execution.id };

return [{ json: { ...c, audit: record } }];

// The Wait node resumes when the rep clicks Approve/Reject in Slack
// (GET <resumeUrl>?decision=approve|reject) or after the timeout.
const c = $('Write Audit Log').first().json;
const resumed = $input.first().json;
const decisionParam = resumed.query?.decision;
const decision = decisionParam === 'approve' ? 'approved' : decisionParam === 'reject' ? 'rejected' : resumed.query ? 'invalid_link' : 'expired';
const a = c.analysis;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const approved_note = {
  properties: {
    hs_timestamp: new Date().toISOString(),
    hs_note_body: `<p><b>✅ AI follow-up approved by rep</b> (Aircall call #${esc(c.call_id)})</p><p><b>Subject:</b> ${esc(a.follow_up_draft.subject)}</p><p>${esc(a.follow_up_draft.body).replace(/\n/g, '<br>')}</p>`,
  },
  associations: [{ to: { id: c.crm.contact_id }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 202 }] }],
};

return [{ json: { call_id: c.call_id, execution_id: $execution.id, decision, decided_at: new Date().toISOString(), approved_note } }];

// Close the loop in the audit log. The actual send is intentionally left to the
// rep's mailbox / HubSpot (plug a Gmail, Outlook or HubSpot single-send node here).
const d = $('Approval Decision').first().json;
const note = $('HubSpot: Log Approved Follow-up').isExecuted ? $('HubSpot: Log Approved Follow-up').first().json : null;
const store = $getWorkflowStaticData('global');

const entry = (store.audit ?? []).find((r) => r.execution_id === d.execution_id);
if (entry) {
  entry.approval = d.decision;
  entry.approval_decided_at = d.decided_at;
  entry.status = 'completed';
  if (note) entry.approved_note_id = String(note.id);
}

return [{ json: { call_id: d.call_id, decision: d.decision, approved_note_id: note ? String(note.id) : null, audit_updated: Boolean(entry) } }];

// GET /webhook/aircall-metrics → operational metrics from the audit log.
const store = $getWorkflowStaticData('global');
const audit = store.audit ?? [];
const n = audit.length;
const count = (fn) => audit.filter(fn).length;
const rate = (k) => (n ? Math.round((k / n) * 1000) / 10 : null);
const avg = (xs) => (xs.length ? Math.round((xs.reduce((s, x) => s + x, 0) / xs.length) * 100) / 100 : null);
const median = (xs) => {
  if (!xs.length) return null;
  const s = [...xs].sort((x, y) => x - y);
  return s[Math.floor(s.length / 2)];
};
const byKey = (k) => audit.reduce((acc, r) => ({ ...acc, [r[k]]: (acc[r[k]] ?? 0) + 1 }), {});
const decided = audit.filter((r) => ['approved', 'rejected'].includes(r.approval));

return [{
  json: {
    calls_processed: n,
    by_route: byKey('route'),
    by_intent: byKey('intent'),
    automation_rate_pct: rate(count((r) => r.automation_allowed)),
    human_review_rate_pct: rate(count((r) => !r.automation_allowed)),
    avg_ai_confidence: avg(audit.map((r) => r.ai_confidence)),
    median_end_to_end_seconds: median(audit.map((r) => r.end_to_end_seconds).filter((x) => x != null)),
    deals_created: count((r) => r.deal_id),
    tickets_created: count((r) => r.ticket_id),
    new_contacts_created: count((r) => r.is_new_contact),
    follow_up_approval_rate_pct: decided.length ? Math.round((decided.filter((r) => r.approval === 'approved').length / decided.length) * 1000) / 10 : null,
    follow_ups_pending: count((r) => r.approval === 'pending'),
    policy_corrections: count((r) => r.policy_corrections?.length),
    idempotency_keys_tracked: Object.keys(store.processed ?? {}).length,
    recent: audit.slice(0, 10),
  },
}];
